import{_ as r,l as i,o as t,c as s,v as e,p as l,x as o,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"Lost in the Middle","description":"","frontmatter":{"title":"Lost in the Middle","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lost-in-middle.md","filePath":"llm/lost-in-middle.md","lastUpdated":1789023840000}'),E={name:"llm/lost-in-middle.md"};function u(m,a,A,g,c,_){const n=i("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="lost-in-the-middle" tabindex="-1">Lost in the Middle <a class="header-anchor" href="#lost-in-the-middle" aria-label="Permalink to &quot;Lost in the Middle&quot;">​</a></h1><div class="epigraph"><p>相关信息放在输入开头或末尾时，模型往往用得最好；必须去读长上下文中间时，表现会明显下降，即使模型声称支持长窗口。</p><footer>—— Liu、Lin、Hewitt、Paranjape、Bevilacqua、Petroni、Liang，Lost in the Middle: How Language Models Use Long Contexts，TACL 2024</footer></div><p>Nelson F. Liu 等人要回答的不是「窗口能不能塞下」，而是 <strong>塞进去之后，模型会不会用</strong>。他们在多文档问答与合成键值检索上，系统改 <strong>上下文长度</strong> 与 <strong>证据位置</strong>，得到一条反复出现的 U 形曲线：开头（首因）与末尾（近因）高，中间低。GPT-3.5-Turbo 在相关段落位于中间时，多文档问答甚至低于 <strong>闭卷、不给任何文档</strong> 的 56.1%。扩展上下文的对照模型并不自动更会用中间信息。论文先以 arXiv:2307.03172 流传，后发表于 <em>Transactions of the Association for Computational Linguistics</em> 12:157–173（2024）。本篇按控制实验写现象与分析，长窗口产品含义见 <a href="/llm/long-context-vs-rag">长上下文是否取代 RAG</a>；随长度整体不可靠见 <a href="/llm/context-rot">Context Rot</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>提示式系统把任务说明、检索段落、对话历史全部格式化成一段输入。检索增强生成尤其如此：商业问答往往把 \\(k\\) 篇文档拼在问题前面。若模型能稳健使用窗口，那么 <strong>把含答案的那一篇从第 1 位挪到第 \\(k/2\\) 位不应改变准确率</strong>。Liu 等把这一可证伪的命题当成评测协议：要宣称长上下文被稳健使用，必须展示最好位置与最差位置的差距足够小。</p><p>实验材料来自 NaturalQuestions-Open：取 2655 条答案是段落的查询。含答案的文档用 NQ 标注段落；干扰文档用在 MS-MARCO 上微调的 Contriever 检索「相关但不含标注答案」的维基块，按相关性降序排列。通过重排含答案文档的位置来调证据位置，通过增减干扰篇数来调长度。指标是预测里是否出现任一标注短答案。另设 JSON 键值检索：一堆键值对里取指定键的值，把「能不能从窗口里抄到匹配 token」从问答推理里拆出来。</p><h3 id="u-形不是随机抖动" tabindex="-1">U 形不是随机抖动 <a class="header-anchor" href="#u-形不是随机抖动" aria-label="Permalink to &quot;U 形不是随机抖动&quot;">​</a></h3><p>多文档问答上，开源的 MPT-30B-Instruct、LongChat-13B（16K）与闭源的 GPT-3.5-Turbo、Claude-1.3 都呈现开头/末尾高、中间低。加长 \\(k\\) 之后，曲线整体下移——更多干扰不仅是填充，还在降低中间位置的可用度。键值任务上，部分模型能近乎完美，另一些仍在中间位置抄错，说明失败可以发生在 <strong>最简单的匹配</strong> 上，而不必怪多文档推理。扩展窗口的孪生模型（相对其短窗口版本）常常 <strong>重叠</strong>，并不是「训练时见过更长序列就会用中间」。</p><p><span class="marginnote">闭卷准确率是一条不该被忘记的基线。中间位置低于闭卷，意味着错误文档不仅没帮忙，还把参数记忆里本来对的答案挤掉了。把「多检索几篇」当成单调增益，与这条曲线矛盾。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议的要点是 <strong>正交地</strong> 改两个因素。位置：含答案文档放在第 \\(1,2,\\ldots,k\\) 槽，其余槽是干扰。长度：增加不含答案的检索块。文档在提示里编号列出，问题在文档之后（标准阅读顺序）。作者还试过把 \\(k-1\\) 篇干扰随机打乱并在说明里写「随机排序」，U 形仍在，说明不是「用户以为搜索结果按相关性排序」这一先验单独造成的。随机无关文档当干扰的附录趋势相似，相关干扰更接近 RAG。</p><p>开放域对照不再保证恰好一篇含答案。用维基检索答 NaturalQuestions-Open 时，读者模型的准确率在检索器召回率仍在上升之前就饱和：从 20 篇加到 50 篇，GPT-3.5-Turbo 大约只再涨 1.5 个百分点，Claude-1.3 大约 1 个百分点。多给文档提高了「答案在窗口里」的概率，但没有等比例提高「模型读到它」的概率。</p><p>架构与提示消融在第 4 节。编码器-解码器（如 Flan-T5 类）在 <strong>训练长度以内</strong> 对位置更不敏感；超出训练长度后 U 形回来。查询感知上下文（把问题同时放在文档前与文档后）让合成键值任务近乎完美，但对多文档问答的趋势几乎不动——匹配键可以靠双向看见查询，跨段推理不行。未做指令微调的基座同样有 U 形，说明不是 chat 对齐单独引入的位置癖好。</p>',13)),(t(),l(p,null,{default:o(()=>[h(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E9%A2%98%22%5D%20--%3E%20CTX%5B%22k%20%E7%AF%87%E6%96%87%E6%A1%A3%22%5D%0A%20%20CTX%20--%3E%20P1%5B%22%E7%AD%94%E6%A1%88%E5%9C%A8%E5%BC%80%E5%A4%B4%22%5D%0A%20%20CTX%20--%3E%20P2%5B%22%E7%AD%94%E6%A1%88%E5%9C%A8%E4%B8%AD%E9%97%B4%22%5D%0A%20%20CTX%20--%3E%20P3%5B%22%E7%AD%94%E6%A1%88%E5%9C%A8%E6%9C%AB%E5%B0%BE%22%5D%0A%20%20P1%20--%3E%20H%5B%22%E5%87%86%E7%A1%AE%E7%8E%87%E9%AB%98%22%5D%0A%20%20P3%20--%3E%20H%0A%20%20P2%20--%3E%20L%5B%22%E5%87%86%E7%A1%AE%E7%8E%87%E4%BD%8E%20%2F%20%E5%8F%AF%E4%BD%8E%E4%BA%8E%E9%97%AD%E5%8D%B7%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="查询感知为何救不了问答" tabindex="-1">查询感知为何救不了问答 <a class="header-anchor" href="#查询感知为何救不了问答" aria-label="Permalink to &quot;查询感知为何救不了问答&quot;">​</a></h3><p>键值任务的查询是精确的键，文档是扁平 JSON。把键放在两侧，等于让每个位置的注意力都能「看到要找什么」，中间槽的匹配不再依赖长程把查询从文末传回。多文档问答的查询是自然语言，答案在段落里，还要避开相关干扰。双向放置查询不改变「中间段落被两头的高注意力槽抢走」这一结构。因此：能用查询感知验收「模型是否会抄 JSON」，不能用它宣称 RAG 已经位置鲁棒。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>U 形与 <a href="/llm/attention-sink">注意力汇点</a> 相关但不相同。汇点解释文首若干 token 为何吸走质量，有助于理解首因；近因则更符合因果解码：生成时最近的键仍在窗口末端，容易拿到质量。中间位置两头不靠，既不是汇点，也不是最近上下文。训练若以短序列为主，对「在序列中部做精确检索」的监督不足。这与后来 Chroma 的腐烂报告、Du 等的「长度本身伤害推理」兼容：Liu 等钉的是 <strong>位置</strong>，后两者钉的是 <strong>长度与内容结构</strong>；一条完整的长上下文验收应同时扫位置与长度。</p><p>编码器-解码器在双向编码器里让所有文档位置对称地看见查询，故训练长度内更平。一旦外推，位置编码与注意力模式离开训练流形，U 形重现——「架构更对称」不是无限长度的豁免。指令微调改变格式遵循，不保证改变位置使用。</p><p><span class="marginnote">不要把 U 形理解成「永远把证据贴在最后就好」。近因在实验里有效，是因为生成紧挨着文末。系统提示、工具说明、上一轮长工具输出若占满末端，用户刚检索到的中间段落照样丢。位置是相对「当前生成点」的，不是绝对文件坐标。</span></p><h3 id="对-rag-流水线的直接推论" tabindex="-1">对 RAG 流水线的直接推论 <a class="header-anchor" href="#对-rag-流水线的直接推论" aria-label="Permalink to &quot;对 RAG 流水线的直接推论&quot;">​</a></h3><p>检索 \\(k\\) 增大有两面：召回上升，读者负担上升。Liu 等的开放域数字说明第二面很快占上风。实践上应：重排后把 <strong>最可能的一两篇放在两端</strong>（或问题紧邻证据）；用压缩器丢掉中间的近重复（见 <a href="/llm/retrieval-based-compaction">RECOMP</a>）；不要假设「长窗口模型 = 可以乱序堆 50 篇」。评测新模型时，除平均准确率外应报 <strong>位置最差档</strong> 与 <strong>位置最好档</strong> 的差，这是原文明确提出的协议。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>论文模型是 2023 年前后的 4k–100k 级。后续长窗口模型把 NIAH 刷高，并不自动取消 U 形：Chroma 在更新的模型上仍看到长度敏感；位置扫描仍应做。NQ 段落设定保证恰好一篇含答案，真实检索可能零篇或多篇，曲线会变形，但「中间更难」的方向在后续复现里反复出现。编码器-解码器的稳健性只在训练长度内被证明；把 FLAN 式模型接到超长窗口上，需要单独测，不能引用第 4.1 节当无限外推。</p><p>提示技巧（重复查询、把证据移到生成点旁）是推理期补丁，不是训练期位置不变性。要在权重里消除 U 形，需要在中部位置上给检索与推理监督，或改注意力结构；那超出原文范围。</p><p><span class="marginnote">U 形是现象，不是一条可反传的损失项。有人用注意力可视化「证明」中间没被看，但权重高不等于值贡献大。仍应以任务准确率对位置作图为准，可视化当辅证。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Lost in the Middle 用控制实验表明：长上下文里证据的位置会显著改变使用效果，典型是两端高、中间低。</li><li>多文档问答上，中间位置可以低于闭卷基线；加长干扰文档使曲线整体下移。</li><li>键值检索把失败从「推理」里拆出：有的模型连中间匹配都会抄错。</li><li>开放域读者准确率在检索召回饱和前就饱和；盲目加大 \\(k\\) 收益很小。</li><li>查询双向放置几乎只救合成匹配；编码器-解码器仅在训练长度内更平。</li><li>出处：Liu 等，<em>Lost in the Middle: How Language Models Use Long Contexts</em>，TACL 12:157–173，2024（arXiv:2307.03172）。</li></ul>',14))])}const f=r(E,[["render",u]]);export{C as __pageData,f as default};
